mapper.select:
/* EmailVerificationMapper.findLatestByEmail */
SELECT id, email, code, verified, expires_at, created_at
FROM email_verification
WHERE email = #{email}
ORDER BY created_at DESC
LIMIT 1

mapper.insert:
/* EmailVerificationMapper.insertVerification */
INSERT INTO email_verification (email, code, verified, expires_at, created_at)
VALUES (#{email}, #{code}, #{verified}, #{expiresAt}, #{createdAt})

mapper.delete:
/* EmailVerificationMapper.deleteByEmail */
DELETE FROM email_verification
WHERE email = #{email}
